    while u != 1 and v != 1:
        if u < v:
            u, v = v, u
        if u in g[v]:
            ch += 1
        v = g[v][0]
    return ch == 0

def intersect(tree, subtrees, depth):
    result = [-1]
    for b, subtree in subtrees:
        distance = 0
        cur = depth[b]
        for leaf in subtree:
            distance += query_1(cur, leaf)
            if distance <= depth[b]:
                result[-1] += 1
                break
            cur = query_1(leaf, cur)
    result[-1] += 1
    return result

def query_3(d, subtrees, roots, g, x):
    intersection = 0
    children_checked = set()
    for subtree in subtrees:
        start = subtree[0]
        if not query_1(d, start):
            continue
        children_checked.update(p for _, p in subtree)
    subtrees.extend([(start + 1, leaf) for leaf in g[start] if leaf not in children_checked])
    if all(leaf in roots for leaf in roots):
        return True
    if (start - 1) not in roots:
        return intersection == 0
    intersection += query_3(d, subtrees, roots, g, x - (start - 1))
    subtree = subtree = [depth[find(start)] for start in subtrees]
