from collections import defaultdict, deque

def find_subtree_size(graph, subtrees, parent, node):
    subtree_size = 1
    queue = deque([node])
    visited = set([node])
    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                subtree_size += 1
                queue.append(neighbor)
                subtrees[neighbor] += subtree_size
                parent[neighbor] = current
    return subtree_size

def get_common_subtree(graph, subtrees, parent, query):
    node1, node2 = query
    previous = parent[node1]
    common_size = 0
    while previous != 0:
        if subtrees[query[1]] and subtrees[query[1]] == subtrees[previous]:
            common_size = subtrees[query[1]]
        if parent[previous] == previous:
            break
        previous = parent[previous]
    return common_size

def check_intersection(span1, span2, subtrees, parent):
    common_nodes = get_common_subtree(span1[0], span1[1], subtrees, parent)
    if common_nodes < span1[2] or common_nodes > span1[1] or common_nodes < span2[0] or common_nodes > span2[1]:
        return False
    common_nodes -= 1
    span = (min(span1[0], span2[0]), max(span1[1], span2[1]), common_nodes + 1)
    common_subtrees = find_subtree_size(graph, subtrees, parent, span)
    return common_subtrees[span[1]] == common_subtrees[span[2]]

def check_intersection_all_queries(span, subtrees, parent):
    for query in queries:
        if not check_intersection(span, query, subtrees, parent):
            return False
    return True

