from collections import defaultdict

def count_subquads(n, q):
    # Dictionary to count occurrences of each color in a square
    color_counts = defaultdict(int)

    for row in range(1, n+1):
        for col in range(1, n+1):
            c = row*10 + col
            if c > n*n:
                continue
            color_counts[c] += 1

    # Determine the maximum number of colors Kostya wants to have in any subsquare
    max_colors_in_subsquare = q

    count = 0
    for attempt in range(1, min(n+1, max_colors_in_subsquare)+1):
        valid = True
        for row in range(1, n+1):
            for col in range(1, n+1):
                c = row*10 + col
                if c > n*n:
                    continue
                if color_counts[c] == attempt:
                    continue
                valid = False
                break
            if not valid:
                break
        if valid:
            count += (attempt ** 2) - attempt

        if count >= n**2:
            break

    return count

