MOD = 10**9 + 7

def count_ways(steps, pieces):
    dp = [[0] * (steps + 1) for _ in range(2)]
    dp[0][0] = 1

    for piece, c1, cR in pieces:
        for i in range(steps, -1, -1):
            for j in range(steps + 1):
                if dp[(i + 1) % 2][j] > 0:
                    if piece == 'P':
                        dp[i & 1][j] = (dp[i & 1][j] + dp[(i + 1) % 2][j]) % MOD
                    elif piece == 'R' or piece == 'K':
                        dp[i & 1][j + (step % 2) + 1] = (dp[i & 1][j + (step % 2) + 1] + dp[(i + 1) % 2][j]) % MOD
                    elif piece == 'B':
                        dp[i & 1][j + (step + step % 2) // 2 + 1] = (dp[i & 1][j + (step + step % 2) // 2 + 1] + dp[(i + 1) % 2][j]) % MOD
                    elif piece == 'Q':
                        dp[i & 1][j + 2 if step & 1 else 2] = (dp[i & 1][j + 2 if step & 1 else 2] + dp[(i + 1) % 2][j]) % MOD
        for k in range(steps + 1):
            dp[i & 1][k] = dp[i & 1][k] % MOD

    return sum(dp[0] if piece == 'P' else dp[1] for piece, _, _ in pieces), dp[0][0]

