def min_target_time(n, s, x, v, t):
    # Calculate the time it takes for a person to reach 0 or 10^6 based on their coordinates and speeds
    def reach_point(coord, speed):
        if speed == -1:
            return float('inf')
        time_to_reach = abs(coord) / speed
        if coord < 0:
            return time_to_reach
        elif coord == 0:
            return 0.0
        else:
            # Calculate the time to reach 0 if there's a roaming speed limit
            roaming_speed = math.sqrt(speed * speed - (coord ** 2))
            time_to_reach = time_to_reach + (t * v - abs(roaming_speed))
            if time_to_reach >= 0:
                return 0.0
            else:
                return time_to_reach + (abs(roaming_speed) * v)

    # If any person reaches 0 or 10^6, or if both people have the same speed limit effect on each other
    if any(miner.reach_point(coord, speed) == 0.0 for miner in speeds for (coord, speed) in miner.people.values()):
        return 0.0

    # Use binary search to find the minimum time
    left, right = 0, min(reach_point(x, v), reach_point(10**6, v)) - 0.00001
    while right - left > 0.00001:
        mid = (left + right) / 2
        found = False
        for miner in speeds:
            # Check if the bomber can reach any of the target points at time mid
            if miners[miner][0](mid) > 0 or miners[miner][1](mid) > 0:
                found = True
                break
        if found:
            right = mid
        else:
            left = mid
    return right

