from collections import defaultdict, Counter
import queue

class Tree:
    def __init__(self, n):
        self.n = n
        self.data = [[] for _ in range(n)]
        self.dist = defaultdict(set)

    def add_edge(self, u, v):
        self.data[u].append(v)
        self.data[v].append(u)

    def find_shortest_paths(self, start, end, dist):
        dist[start] = 0
        dist_end = float('inf')
        q = queue.Queue()
        q.put((start, 0))

        while not q.empty():
            u, d = q.get()
            for v in self.data[u]:
                if dist_end > d + 1 and v == end:
                    dist_end = d + 1
                elif d + 1 < dist[v] and v not in self.dist[u]:
                    self.dist[u].add(v)
                    dist[v] = d + 1
                    q.put((v, d + 1))

        if dist_end == float('inf'):
            return None, None

        shortest_path = [start]
        level = dist_end
        while level and shortest_path[-1] != end:
            for u in self.dist[shortest_path[-1]]:
                dist_u = level - 1
                if dist_u <= dist[u]:
                    self.dist[shortest_path[-1]].difference_update({u})
                    if dist_u in dist:
                        if (dist_u-1, dist_u) not in shortest_path:
                            shortest_path.append((dist_u-1, dist_u))

                        for v in self.data[u]:
                            if dist_end > dist[v] and (dist_u+1, dist_u) not in shortest_path and v != shortest_path[-1]:
                                self.dist[u].difference_update({v})
                                shortest_path.append((dist_u+1, dist_u))
                    break

        return shortest_path, dist_end
