def expected_length(n, k, m):
    if n > m:
        return expected_length(m, k, n)

    if k == 1:
        return Fraction(1, 1)

    prob_large_multiverse = Fraction(1, 1 + m - n)
    prob_small_multiverse = Fraction(1, m - n)
    prob_link_broken = Fraction(1, m - n - 1)
