import sys

def optimal_tree_root_labels(n, parents):
    preorder = list(range(n))
    arrange_canonical_form(preorder, parents)
    return preorder

def arrange_canonical_form(labels, parents):
    stack = [0]
    edges = [[] for _ in range(n)]

    for i in range(1, len(labels)):
        p = parents[i-1]

        # Ensuring vertex labels stay integers
        new_idx = labels[i]
        while stack and labels[labels[stack[-1]]] > new_idx:
            p = parents[labels[stack.pop()]]

        # If the vertex is its parent
        if labels[stack[-1]] == p:
            parents[i] = p

        while stack and labels[labels[stack[-1]]] > new_idx:
            labels[labels[stack.pop()]] = new_idx

        edges[p].append(i)
        edges[new_idx].append(i)
        labels[i] = new_idx

    for i in range(len(parents)):
        while labels[i] > 0 and children_count(parents, i) % 2 != edges[labels[i]][edges[labels[i]][0]][1] % 2:
            if labels[i] > 0 and children_count(parents, i) % 2 == 1:
                parents[labels[i]] = edges[labels[i]][0]
        if labels[i] == 0:
            parents[i] = -1*parents[i]

def children_count(parents, root):
    count = 0
    for p in edges[parents[root]]:
        count += 1
        count += children_count(parents, p)
    return 2*count


if __name__ == "__main__":
    n = int(input().strip())
    p = list(map(int, input().strip().split()))
    print(optimal_tree_root_labels(n, p))
